constraint.cypher:
MATCH (vm:Eclipse:ViewModelType)
WHERE coalesce(vm.abstract, false) = false
  AND EXISTS { MATCH (vm)<-[:CONTAINS]-(vmb:Osgi:Bundle) WHERE vmb:Osgi:Analyzed }
  AND NOT EXISTS {
        MATCH (vm)-[:EXTENDS|IMPLEMENTS*0..]->(ancestor:Type)
              <-[:TESTS_TYPE]-(:Eclipse:PropertyTester)
      }
RETURN vm.fqn AS UncoveredViewModelType
ORDER BY UncoveredViewModelType
